          "/src/toaster.js": `import { inject, reactive, readonly } from "vue";

// How long each type stays on screen by default (ms). 0 means "until closed".
const DEFAULT_DURATION = { success: 3000, info: 3000, error: 5000 };

export const ToasterKey = Symbol("toaster");

// One toaster per app: a reactive list plus the functions that change it.
export function createToaster() {
  const toasts = reactive([]);
  let nextId = 1;

  function toast(message, options = {}) {
    const type = options.type || "info";
    const duration = options.duration ?? DEFAULT_DURATION[type];
    const id = nextId++;
    toasts.unshift({ id, type, message, duration }); // newest first
    return id;
  }
  toast.success = (message, options) =>
    toast(message, { ...options, type: "success" });
  toast.error = (message, options) =>
    toast(message, { ...options, type: "error" });
  toast.info = (message, options) =>
    toast(message, { ...options, type: "info" });
  toast.dismiss = (id) => {
    if (id === undefined) return toasts.splice(0);
    const index = toasts.findIndex((t) => t.id === id);
    if (index !== -1) toasts.splice(index, 1);
  };

  // Consumers get a read-only view: only toast() and dismiss() may change it.
  return { toasts: readonly(toasts), toast };
}

export function useToaster() {
  const toaster = inject(ToasterKey, null);
  if (!toaster)
    throw new Error("useToast() needs a toaster provided by an ancestor");
  return toaster;
}

export function useToast() {
  return useToaster().toast;
}
`,
